questionvariables.text:
slist: [["AD","BG",8,13,5,["CBG","FGB"],["CGB","ABG","DBG","CBG"],[["CGB","Angle CGB is the other acute angle of triangle CBG: it is between GC and GB. Move AD to CB, which is parallel to it and meets BG at B."],["ABG","The lines that make angle ABG are AB and BG; AB is not parallel to AD. Move AD to CB, which is parallel to it and meets BG at B."],["DBG","The lines that make angle DBG are DB and BG; DB is not parallel to AD. Move AD to CB, which is parallel to it and meets BG at B."]]],["AD","FH",18,4,12,["EHF","GFH"],["DHF","EFH","EHF","AHF"],[["EFH","Angle EFH is the other acute angle of triangle EHF: it is between FE and FH. Move AD to EH, which is parallel to it and meets FH at H."],["DHF","The lines that make angle DHF are DH and HF; DH is not parallel to AD. Move AD to EH, which is parallel to it and meets FH at H."],["AHF","The lines that make angle AHF are AH and HF; AH is not parallel to AD. Move AD to EH, which is parallel to it and meets FH at H."]]],["BC","DE",19,14,9,["ADE","HED"],["AED","BDE","CDE","ADE"],[["AED","Angle AED is the other acute angle of triangle ADE: it is between EA and ED. Move BC to AD, which is parallel to it and meets DE at D."],["BDE","The lines that make angle BDE are BD and DE; BD is not parallel to BC. Move BC to AD, which is parallel to it and meets DE at D."],["CDE","The lines that make angle CDE are CD and DE; CD is not parallel to BC. Move BC to AD, which is parallel to it and meets DE at D."]]],["EF","BD",23,17,15,["ABD","CDB"],["FBD","ADB","ABD","EBD"],[["ADB","Angle ADB is the other acute angle of triangle ABD: it is between DA and DB. Move EF to AB, which is parallel to it and meets BD at B."],["FBD","The lines that make angle FBD are FB and BD; FB is not parallel to EF. Move EF to AB, which is parallel to it and meets BD at B."],["EBD","The lines that make angle EBD are EB and BD; EB is not parallel to EF. Move EF to AB, which is parallel to it and meets BD at B."]]],["EH","AC",24,16,13,["BCA","DAC"],["ECA","BCA","BAC"],[["BAC","Angle BAC is the other acute angle of triangle BCA: it is between AB and AC. Move EH to BC, which is parallel to it and meets AC at C."],["ECA","The lines that make angle ECA are EC and CA; EC is not parallel to EH. Move EH to BC, which is parallel to it and meets AC at C."]]],["FG","AH",8,11,7,["DAH","EHA"],["FAH","DHA","DAH"],[["DHA","Angle DHA is the other acute angle of triangle DAH: it is between HD and HA. Move FG to DA, which is parallel to it and meets AH at A."],["FAH","The lines that make angle FAH are FA and AH; FA is not parallel to FG. Move FG to DA, which is parallel to it and meets AH at A."]]],["DC","AF",10,18,13,["BAF","EFA"],["CAF","BFA","DAF","BAF"],[["BFA","Angle BFA is the other acute angle of triangle BAF: it is between FB and FA. Move DC to BA, which is parallel to it and meets AF at A."],["CAF","The lines that make angle CAF are CA and AF; CA is not parallel to DC. Move DC to BA, which is parallel to it and meets AF at A."],["DAF","The lines that make angle DAF are DA and AF; DA is not parallel to DC. Move DC to BA, which is parallel to it and meets AF at A."]]],["GH","BE",25,16,5,["ABE","FEB"],["AEB","GBE","ABE"],[["AEB","Angle AEB is the other acute angle of triangle ABE: it is between EA and EB. Move GH to AB, which is parallel to it and meets BE at B."],["GBE","The lines that make angle GBE are GB and BE; GB is not parallel to GH. Move GH to AB, which is parallel to it and meets BE at B."]]],["BF","DG",6,13,8,["CGD","HDG"],["CDG","BGD","FGD","CGD"],[["CDG","Angle CDG is the other acute angle of triangle CGD: it is between DC and DG. Move BF to CG, which is parallel to it and meets DG at G."],["BGD","The lines that make angle BGD are BG and GD; BG is not parallel to BF. Move BF to CG, which is parallel to it and meets DG at G."],["FGD","The lines that make angle FGD are FG and GD; FG is not parallel to BF. Move BF to CG, which is parallel to it and meets DG at G."]]],["AE","CH",6,11,9,["DHC","GCH"],["DCH","EHC","AHC","DHC"],[["DCH","Angle DCH is the other acute angle of triangle DHC: it is between CD and CH. Move AE to DH, which is parallel to it and meets CH at H."],["EHC","The lines that make angle EHC are EH and HC; EH is not parallel to AE. Move AE to DH, which is parallel to it and meets CH at H."],["AHC","The lines that make angle AHC are AH and HC; AH is not parallel to AE. Move AE to DH, which is parallel to it and meets CH at H."]]]];
/* Design: angle between skew lines in a cuboid (translate one line until it meets the other). Every angle sits in a right-angled face triangle XPY (right angle at X) whose two shorter sides are edges, so no Pythagoras is needed. Source: adapted from SMP Book 5 (Metric), Chapter 13, 2.5. */
ix: 1+rand(10); SS: slist[ix];
L1: SS[1]; L2: SS[2]; ll: SS[3]; ww: SS[4]; hh: SS[5]; good: SS[6]; OP: SS[7]; DF: SS[8];
LS: "ABCDEFGH"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[0,0,hh],[ll,0,hh],[ll,ww,hh],[0,ww,hh]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
nm: first(sublist(OP, lambda([o], member(o, good))));
XX: charat(nm,1); PV: charat(nm,2); YY: charat(nm,3);
XP: sconcat(XX,PV); XY: sconcat(XX,YY); XPY: sconcat(XX,PV,YY); PY: sconcat(PV,YY);
uu: sqrt(sq(XP)); vv2: sqrt(sq(XY));
th: angd(nm); cp: 90-th; thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = nm), o], o, OP);
o1: DF[1][1]; o2: DF[2][1]; o3: last(DF)[1];

feedbackvariables.text:
rvs(s) := sconcat(charat(s,2), charat(s,1));
a1: sconcat(charat(ans1,2), charat(ans1,1)); a3: sconcat(charat(ans1,2), charat(ans1,3));
oarm: if is(a3 = L2 or a3 = rvs(L2)) then a1 else a3;

d3(v) := dispdp(float(floor(1000*v+1/2)/1000),3);
okr: is(ans2 > 0 and ans2 < 90); rdn: float(ans2*%pi/180);
tn: if okr then float(tan(rdn)) else NA;
